let lang='en';
const t=k=>(I18N[lang]&&I18N[lang][k])||I18N.en[k]||k;
const lvlIdx=a=>a<=50?0:a<=100?1:a<=150?2:a<=200?3:a<=300?4:5;
const lvlName=a=>t('lvl'+lvlIdxScaled(a));
function applyI18n(){document.documentElement.lang=lang==='zh'?'zh':lang==='ms'?'ms':lang==='ta'?'ta':'en';$$('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));const si=$('#sinput');if(si)si.placeholder=t('searchPh');if(!hasNotify){const el=$('[data-i18n="notifS"]');if(el)el.textContent=t('noNotif')+(/iPad|iPhone|iPod/.test(navigator.userAgent)?' '+t('hsHint'):'')}}
const levelColor=a=>!Number.isFinite(a)?'#2878d0':LVL_COLOR[lvlIdxScaled(a)];
const usAqiToC=a=>{const bp=[[0,50,0,9],[51,100,9.1,35.4],[101,150,35.5,55.4],[151,200,55.5,125.4],[201,300,125.5,225.4],[301,500,225.5,325.4]];for(const[al,ah,cl,ch]of bp)if(a<=ah)return cl+Math.max(0,a-al)*(ch-cl)/(ah-al);return 325.4};
const cToMyApi=c=>{const bp=[[0,50,0,35],[51,100,35,75],[101,200,75,150],[201,300,150,250],[301,500,250,500]];for(const[il,ih,cl,ch]of bp)if(c<=ch)return Math.round(il+Math.max(0,c-cl)*(ih-il)/(ch-cl));return 500};
const toMyApi=a=>Number.isFinite(a)?cToMyApi(usAqiToC(a)):a;
const dispVal=a=>settings.scale==='api'?toMyApi(a):a;
const scaleTag=()=>settings.scale==='api'?'API':'AQI';
const LVL_CLASS=['good','moderate','sensitive','unhealthy','very unhealthy','hazardous'];
const LVL_COLOR=['#4c986e','#d0a044','#dc864c','#cc5c48','#854a61','#854a61'];
const lvlIdxScaled=a=>{const v=dispVal(a);return settings.scale==='api'?(v<=50?0:v<=100?1:v<=200?3:v<=300?4:5):lvlIdx(v)};
const distance=(a,b)=>{const dy=(a.lat-b.lat)*111,dx=(a.lon-b.lon)*111*Math.cos(((a.lat+b.lat)/2)*Math.PI/180);return Math.hypot(dx,dy)};
function flyToOffset(latlng,zoom){if(!leafletMap)return;
// Offsets are relative to the MAP CONTAINER. Mobile: container is already clipped to the
// visible area (top:54px, bottom:58%), so no offset. Desktop: container is full-viewport
// with the header (68px) and card (450px + 20px margin, right) overlaying it.
const desktop=window.innerWidth>720;const dx=desktop?-235:0,dy=desktop?34:0;
const p=leafletMap.project(latlng,zoom).subtract([dx,dy]);leafletMap.flyTo(leafletMap.unproject(p,zoom),zoom)}
function setUserLocation(lat,lon,label,approximate=false,zoom=8){userLocation={lat,lon,approx:approximate,label:(approximate?t('approx'):'')+(label||t('yourloc'))};$('#location').classList.toggle('approx',approximate);hasFittedLocation=zoom>8;if(!leafletMap)return;if(userMarker)leafletMap.removeLayer(userMarker);userMarker=L.marker([lat,lon],{pane:'user',interactive:false,icon:L.divIcon({className:'',html:'<div class="user-dot" style="--dot:'+levelColor(current?.aqi)+'"></div>',iconSize:[18,18],iconAnchor:[9,9]})}).addTo(leafletMap);flyToOffset([lat,lon],zoom)}
function setSearchMarker(lat,lon){if(!leafletMap)return;clearSearchMarker();searchMarker=L.marker([lat,lon],{pane:'user',interactive:false,icon:L.divIcon({className:'',html:'<div class="user-dot" style="--dot:#2878d0"></div>',iconSize:[18,18],iconAnchor:[9,9]})}).addTo(leafletMap)}
function clearSearchMarker(){if(searchMarker&&leafletMap){leafletMap.removeLayer(searchMarker)}searchMarker=null}
function fitNearby(){if(!leafletMap||!userLocation||hasFittedLocation||!stations.length)return;const nearest=stations.filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lon)).sort((a,b)=>distance(userLocation,a)-distance(userLocation,b)).slice(0,8);if(!nearest.length)return;const points=[[userLocation.lat,userLocation.lon],...nearest.map(s=>[s.lat,s.lon])];const pad=window.innerWidth>720?L.point(530,120):L.point(60,80);const zoom=Math.min(leafletMap.getBoundsZoom(L.latLngBounds(points),false,pad),8);flyToOffset([userLocation.lat,userLocation.lon],zoom);hasFittedLocation=true}
const advice=a=>{const i=Math.min(lvlIdx(a),4);const body=(i===1||i===2)&&settings.sensitive?t('adv'+i+'Bs'):t('adv'+i+'B');return[t('adv'+i+'T'),body]};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.add('hidden'),3500)}
function render(){const card=$('.card'),sc=card?card.scrollTop:0;const h=advice(current.aqi);$('#place').textContent=userLocation?.label||current.name;const sevColor=levelColor(current.aqi);const k2=adviceKey(),isAI=aiKey===k2&&!!aiText,waiting=!demo&&!isAI&&!aiFailed[k2];const upd=!demo&&current.time?` · ${t('updated')} ${new Date(current.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`:'';$('#now').innerHTML=`<div class="live">${demo?t('sample'):t('live')+esc(upd)}</div><div class="heading"><div><p>${t('monitor')} · ${esc(current.name.toUpperCase())}</p><h1 style="color:${sevColor}">${lvlName(current.aqi)}</h1></div><div class="weather">☁ ${current.temperature??'—'}°</div></div><div class="score"><strong style="color:${sevColor}">${dispVal(current.aqi)??'—'}</strong><span>${settings.scale==='api'?t('myapi'):t('usaqi')}<br><small>${userLocation?Math.round(distance(userLocation,current))+' '+t('fromyou')+(userLocation.approx?' · '+t('approx').trim():''):t('reading')}</small><button id="scale-toggle" class="scale-btn">⇄ ${settings.scale==='api'?'US AQI':'API (MY)'}</button></span></div><div class="advice"><i style="background:${sevColor}">!</i><span><b>${h[0]}<span id="advice-wait" class="spin${waiting?'':' hidden'}">◌</span></b><span id="advice-body">${isAI?esc(aiText):waiting?'…':esc(h[1])}</span><small id="ai-stamp" class="ai-stamp${isAI?'':' hidden'}">${t('aiStamp')}</small></span></div><div class="metrics"><div class="metric"><span>PM2.5</span><b>${current.pm25??'—'}</b><small>µg/m³</small></div><div class="metric"><span>${t('humidity')}</span><b>${current.humidity??'—'}</b><small>%</small></div><div class="metric"><span>${t('wind')}</span><b>${current.wind??'—'}</b><small>km/h</small></div></div><button class="alert" id="alert" aria-label="${t('alertT')}"><span><b>${t('alertT')}</b><small>${t('alertS')}</small></span><b>→</b></button>`;$('#alert').onclick=()=>$('#modal').classList.remove('hidden');$('#scale-toggle').onclick=()=>{settings.scale=settings.scale==='api'?'aqi':'api';localStorage.setItem('airly-settings',JSON.stringify(settings));render()};if(userMarker)userMarker.getElement()?.querySelector('.user-dot')?.style.setProperty('--dot',levelColor(current.aqi));const ticks=settings.scale==='api'?['0','50','100','200','300','500']:['0','50','100','150','200','300+'];$$('.legend>div:last-child span').forEach((el,i)=>{if(ticks[i])el.textContent=ticks[i]});renderMap();renderNearby();if(!$('#trend').classList.contains('hidden'))renderTrend();if(card)card.scrollTop=sc;loadAdvice()}
function selectStation(st){current=st;render();enrichStation(st)}
async function enrichStation(st){if(!Number.isFinite(st.uid))return;try{const r=await fetch('/api/air?uid='+st.uid);if(!r.ok)return;const d=await r.json();if(!Number.isFinite(d.aqi)||current.uid!==st.uid)return;current={...st,...d,name:st.name||d.name};trendData={name:current.name,forecast:d.forecast||[]};render()}catch{}}
let mapSig='';
